from datetime import timedelta
from pathlib import Path
import sqlite3

import categories
import config
import database
import models
import training_verification


TABLE_NAMES = {
    'directions', 'bundles', 'clubs', 'series', 'events', 'event_provenance',
    'users', 'user_directions', 'favorites', 'interactions', 'friendships',
    'invitations', 'app_settings', 'import_log', 'training_imports', 'training_history',
}
PRIVATE_COUNTS_SQL = '''SELECT
    (SELECT COUNT(*) FROM clubs), (SELECT COUNT(*) FROM users),
    (SELECT COUNT(*) FROM user_directions), (SELECT COUNT(*) FROM favorites),
    (SELECT COUNT(*) FROM interactions), (SELECT COUNT(*) FROM friendships),
    (SELECT COUNT(*) FROM invitations), (SELECT COUNT(*) FROM import_log),
    (SELECT COUNT(*) FROM training_imports), (SELECT COUNT(*) FROM training_history)'''
TARGET_COUNTS_SQL = '''SELECT
    (SELECT COUNT(*) FROM directions), (SELECT COUNT(*) FROM bundles),
    (SELECT COUNT(*) FROM clubs), (SELECT COUNT(*) FROM series),
    (SELECT COUNT(*) FROM events), (SELECT COUNT(*) FROM event_provenance),
    (SELECT COUNT(*) FROM users), (SELECT COUNT(*) FROM user_directions),
    (SELECT COUNT(*) FROM favorites), (SELECT COUNT(*) FROM interactions),
    (SELECT COUNT(*) FROM friendships), (SELECT COUNT(*) FROM invitations),
    (SELECT COUNT(*) FROM app_settings), (SELECT COUNT(*) FROM import_log),
    (SELECT COUNT(*) FROM training_imports), (SELECT COUNT(*) FROM training_history)'''


def _table_names(connection):
    """Read the actual user-table names without constructing SQL from identifiers."""
    rows = connection.execute("SELECT name FROM sqlite_master WHERE type='table'").fetchall()
    return {row[0] for row in rows}


def _has_schema_extras(connection):
    """Detect schema objects that are unnecessary in the reviewed public catalogue."""
    return connection.execute('''SELECT 1 FROM sqlite_master
        WHERE type IN ('view','trigger') OR (type='index' AND sql IS NOT NULL)
        LIMIT 1''').fetchone() is not None


def _matches_application_schema(connection):
    """Reject hidden columns or altered constraints before copying a whole database file."""
    expected = database.get_connection(':memory:')
    try:
        database.init_db(expected)
        statement = "SELECT name,sql FROM sqlite_master WHERE type='table'"
        definitions = dict(expected.execute(statement).fetchall())
        actual = dict(connection.execute(statement).fetchall())
        if set(actual) != set(definitions):
            return False
        for name, sql in definitions.items():
            if database._normalized_schema(actual[name]) != database._normalized_schema(sql):
                return False
        return True
    finally:
        expected.close()


def _is_pristine(connection):
    """Allow an empty file or the complete empty app schema, preserving every occupied target."""
    names = _table_names(connection)
    if not names:
        objects = connection.execute('SELECT 1 FROM sqlite_master LIMIT 1').fetchone()
        return objects is None
    if names != TABLE_NAMES:
        return False
    if any(connection.execute(TARGET_COUNTS_SQL).fetchone()):
        return False
    return not _has_schema_extras(connection) and _matches_application_schema(connection)


def _validate_courses(connection):
    """Require the public-field whitelist used by the reviewed catalogue builder."""
    rows = connection.execute('SELECT * FROM series ORDER BY id').fetchall()
    if not 0 < len(rows) <= config.MAX_RECORDS_PER_SOURCE:
        raise ValueError('The starter must contain a bounded nonempty set of public courses.')
    for row in rows:
        if (row['id'] <= 0 or row['source'] != 'unisport'
                or not row['external_id'].startswith(config.HISTORY_PATTERN_PREFIX)
                or not row['title'] or not row['title'].isprintable()
                or row['description'] != config.TRAINING_CATALOGUE_DESCRIPTION
                or row['organizer'] != 'Unisport HSG' or row['event_type'] != ''
                or row['source_url'] != config.UNISPORT_PUBLIC_SCHEDULE_URL
                or row['registration_url'] != '' or row['price_rappen'] is not None
                or row['club_id'] is not None or row['location'] != ''
                or row['location_type'] != 'tba' or row['level'] != ''
                or row['members_only'] != 0 or row['is_recurring'] != 1
                or row['is_placeholder'] != 0):
            raise ValueError('The starter contains an unapproved course field.')
        if row['title'] == config.UNREVIEWED_ACTIVITY_TITLE and row['sport'] != '':
            raise ValueError('Unreviewed course labels must remain masked.')


def _validate_events(connection):
    """Require valid dated provenance, unknown availability and public evidence URLs."""
    count = connection.execute('SELECT COUNT(*) FROM events').fetchone()[0]
    proof_count = connection.execute('SELECT COUNT(*) FROM event_provenance').fetchone()[0]
    if not 0 < count <= config.MAX_RECORDS_PER_SOURCE or count != proof_count:
        raise ValueError('Every bounded starter occurrence needs its own provenance.')
    bounds = connection.execute('SELECT MIN(start_time),MAX(start_time) FROM events').fetchone()
    first = database.from_db_text(bounds[0])
    end = database.from_db_text(bounds[1]) + timedelta(seconds=1)
    rows = database.get_event_records(connection, first, end)
    if len(rows) != count:
        raise ValueError('The starter contains unjoinable activity rows.')
    for row in rows:
        event = models.event_from_row(row)
        if (database.to_db_text(event.start) != row['start_time']
                or database.to_db_text(event.end) != row['end_time']):
            raise ValueError('Starter timestamps must use the canonical local time format.')
        if (event.event_id <= 0 or event.status != 'unknown'
                or row['end_is_estimated'] not in (0, 1)
                or event.provenance_kind not in ('website', 'projected')):
            raise ValueError('Starter occurrences must retain their reviewed uncertainty.')
        if event.provenance_kind == 'website':
            start, last = training_verification._source_range(event.verification_url)
            if not start <= event.start.date() <= last:
                raise ValueError('The public evidence does not cover its occurrence date.')
    for row in connection.execute('SELECT created_at FROM event_provenance').fetchall():
        if database.to_db_text(database.from_db_text(row[0])) != row[0]:
            raise ValueError('Provenance creation times must use the canonical time format.')


def validate_starter(connection):
    """Validate the published data boundary before a byte of it is copied into the app.

    :param connection: read-only starter connection with the normal sqlite3.Row factory
    :return: None; invalid content raises ValueError
    """
    if _table_names(connection) != TABLE_NAMES or not _matches_application_schema(connection):
        raise ValueError('The starter schema is not the complete application schema.')
    if _has_schema_extras(connection):
        raise ValueError('The starter contains unexpected schema objects.')
    if connection.execute('PRAGMA integrity_check').fetchone()[0] != 'ok':
        raise ValueError('The starter failed its integrity check.')
    if connection.execute('PRAGMA foreign_key_check').fetchone() is not None:
        raise ValueError('The starter contains broken references.')
    if any(connection.execute(PRIVATE_COUNTS_SQL).fetchone()):
        raise ValueError('The public starter must not contain private or demonstration data.')
    settings = dict(connection.execute('SELECT key,value FROM app_settings').fetchall())
    required = {'taxonomy_version', 'catalogue_mode', 'catalogue_id', 'setup_done'}
    if (set(settings) != required or settings['setup_done'] != '1'
            or settings['catalogue_mode'] != config.REVIEWED_CATALOGUE_MODE
            or not settings['catalogue_id'].startswith('reviewed-')):
        raise ValueError('The starter has invalid reviewed-catalogue settings.')
    taxonomy = categories.load_taxonomy()
    if settings['taxonomy_version'] != str(taxonomy['_meta']['version']):
        raise ValueError('The starter taxonomy version does not match the application.')
    _validate_courses(connection)
    _validate_events(connection)


def bootstrap_starter(connection, seed_path=None, enabled=None):
    """Copy a validated public starter only into a pristine file-backed application database.

    :param connection: empty target connection; existing data is never overwritten
    :param seed_path: optional published file path; missing files leave the demo path available
    :param enabled: optional explicit switch; False preserves the separate demo mode
    :return: True after a copy, False for an occupied/disabled/memory/missing-seed target
    """
    enabled = config.USE_PUBLIC_STARTER if enabled is None else enabled
    if not enabled:
        return False
    target = connection.execute('PRAGMA database_list').fetchone()[2]
    if not target:
        return False
    seed = Path(config.PUBLIC_UNISPORT_SEED if seed_path is None else seed_path)
    if not seed.is_file():
        return False
    if seed.resolve() == Path(target).resolve():
        raise ValueError('The public starter must not be used as the writable application file.')
    if connection.in_transaction:
        raise ValueError('Finish the caller transaction before bootstrapping the catalogue.')
    if not _is_pristine(connection):
        return False
    source = None
    try:
        source = database.get_connection(seed.resolve().as_uri() + '?mode=ro', uri=True)
        validate_starter(source)
        # sqlite3.backup copies a consistent database without adding private source archives.
        # The target is empty; future profile writes belong only to this separate working copy.
        source.backup(connection)
    except (sqlite3.Error, TypeError, KeyError, OverflowError):
        raise ValueError('The public starter could not be validated or copied.') from None
    finally:
        if source is not None:
            source.close()
    return True
